export interface Invoice {
  id: string;
  invoiceNumber: string;
  total: number;
  issuedAt: string;
}

function isInvoice(value: unknown): value is Invoice {
  return (
    typeof value === 'object' &&
    value !== null &&
    'id' in value &&
    'invoiceNumber' in value &&
    'total' in value &&
    'issuedAt' in value &&
    typeof (value as Record<string, unknown>).id === 'string' &&
    typeof (value as Record<string, unknown>).invoiceNumber === 'string' &&
    typeof (value as Record<string, unknown>).total === 'number' &&
    typeof (value as Record<string, unknown>).issuedAt === 'string'
  );
}

export async function fetchInvoices(): Promise<Invoice[]> {
  const response = await fetch('/api/invoices');
  if (!response.ok) {
    throw new Error(`Failed to fetch invoices: ${response.statusText}`);
  }
  const data = await response.json() as unknown;
  if (!Array.isArray(data)) {
    throw new Error('Expected invoices to be an array');
  }
  if (!data.every(isInvoice)) {
    throw new Error('Invalid invoice data');
  }
  return data;
}

